      hu: ["Infrastruktúra", "Lakhatás", "Dél", "Nîmes"],
      ro: ["Infrastructură", "Locuințe", "Sud", "Nîmes"],
      en: ["Infrastructure", "Housing", "South", "Nîmes"],
      es: ["Infraestructura", "Vivienda", "Sur", "Nimes"],
